use std::io::{self, BufRead};
use std::process::ExitCode;

use logscan::Stats;

fn main() -> ExitCode {
    let mut stats = Stats::default();
    let mut stdin = io::stdin().lock();
    let mut line = String::new();
    loop {
        line.clear();
        match stdin.read_line(&mut line) {
            Ok(0) => break,
            Ok(_) => stats.add_line(line.trim_end_matches(['\r', '\n'])),
            Err(error) => {
                eprintln!("logscan: cannot read stdin: {error}");
                return ExitCode::from(1);
            }
        }
    }
    println!("lines: {}", stats.lines);
    println!("rejected lines: {}", stats.rejected_lines);
    println!("timestamps: {}", stats.timestamps);
    println!("pairs: {}", stats.pairs);
    println!("words: {}", stats.words);
    ExitCode::SUCCESS
}
mod error;
mod escape;
mod stats;
mod token;

pub use error::LexError;
pub use escape::unescape;
pub use stats::Stats;
pub use token::{tokenize, Token, Tokens};
use crate::token::{tokenize, Token};

/// What a log dump contained, summed over all lines added so far.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Stats {
    pub lines: u64,
    pub rejected_lines: u64,
    pub timestamps: u64,
    pub pairs: u64,
    pub words: u64,
}

impl Stats {
    /// Counts the tokens of one line. A line with a malformed token counts as rejected from that token on.
    pub fn add_line(&mut self, line: &str) {
        self.lines += 1;
        for token in tokenize(line) {
            match token {
                Ok(Token::Timestamp(_)) => self.timestamps += 1,
                Ok(Token::Key(_)) => self.pairs += 1,
                Ok(Token::Word(_)) => self.words += 1,
                Ok(Token::Quoted(_) | Token::Bare(_)) => {}
                Err(_) => {
                    self.rejected_lines += 1;
                    break;
                }
            }
        }
    }
}
