    /// `[...]`, which must be followed by a blank or the end of the line.
    fn read_timestamp(&mut self, open: usize) -> Step<'a> {
        let bytes = self.src.as_bytes();
        let text_start = open + 1;
        let close = match bytes[text_start..].iter().position(|&c| c == b']' || c == b'[') {
            None => return Err(LexError::UnterminatedTimestamp { pos: open }),
            Some(offset) if bytes[text_start + offset] == b'[' => {
                return Err(LexError::NestedBracket {
                    pos: text_start + offset,
                })
            }
            Some(offset) => text_start + offset,
        };
        self.expect_separator(close + 1)?;
        self.pos = close + 1;
        Ok(Some(Token::Timestamp(&self.src[text_start..close])))
    }

