    /// A quote inside the run is an error.
    fn read_word_or_key(&mut self, start: usize) -> Step<'a> {
        let bytes = self.src.as_bytes();
        let end = match bytes[start..]
            .iter()
            .position(|&c| is_blank(c) || c == b'=' || c == b'"')
        {
            None => bytes.len(),
            Some(offset) if bytes[start + offset] == b'"' => {
                return Err(LexError::UnexpectedQuote {
                    pos: start + offset,
                })
            }
            Some(offset) => start + offset,
        };
