fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

/// The index of the first byte at or after `from` that is not a blank.
#[inline]
fn skip_blanks(bytes: &[u8], from: usize) -> usize {
    bytes[from..]
        .iter()
        .position(|&c| !is_blank(c))
        .map_or(bytes.len(), |offset| from + offset)
}

