use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Streams the tokens of one line. After the first error it yields nothing more.
///
/// Where a token may start depends on the token before it: a key is always followed by its
/// value, and every other token by the next token after blanks.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

/// What the next call to [`Tokens::next`] reads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// At the start of a token, possibly after blanks.
    Token,
    /// Right after `=`, so the value of a pair comes next.
    Value,
    /// The line is finished, either at its end or after an error.
    Done,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens {
            src,
            pos: 0,
            state: State::Token,
        }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = match self.state {
            State::Token => {
                let bytes = self.src.as_bytes();
                let start = skip_blanks(bytes, self.pos);
                if start == bytes.len() {
                    self.state = State::Done;
                    return None;
                }
                self.pos = start;
                self.read_token(start)
            }
            State::Value => self.read_value(),
            State::Done => return None,
        };
        match result {
            Ok(token) => Some(Ok(token)),
            Err(error) => {
                // Nothing after an error is trusted, so the rest of the line is dropped.
                self.state = State::Done;
                self.pos = self.src.len();
                Some(Err(error))
            }
        }
    }
}

